import json,urllib.request,sqlite3,os
from pathlib import Path
import daemon
out={}
try:
 cfg=daemon.config()
 out["config"]={"valid":True,"curator_id":cfg["CURATOR_MANAGED_CHAT_ID"],"bridge_local":cfg["base"].startswith("http://127.0.0.1:")}
 for method in ("getMe","getWebhookInfo"):
  try:
   val=daemon.bot(cfg,method,{}).get("result",{})
   if method=="getMe":
    out["telegram_getMe"]={"ok":bool(val.get("is_bot")),"expected_username":str(val.get("username","")).lower()=="neur0store_bot"}
   else:
    out["telegram_getWebhookInfo"]={"webhook_active":bool(val.get("url")),"pending_update_count":val.get("pending_update_count"),"last_error_date_present":bool(val.get("last_error_date"))}
  except Exception as e:out["telegram_"+method]={"ok":False,"error_type":type(e).__name__,"error_code":str(e)[:90] if type(e).__name__=="Blocked" else ""}
 try:
  info=daemon.call(cfg["base"]+"/api/supervisor-watchdog/agent-assignments",timeout=6)
  db=sqlite3.connect("file:"+Path(cfg["db"]).as_posix()+"?mode=ro",uri=True,timeout=2)
  keys=[("telegram-curator-"+str(v),state) for v,state in db.execute("SELECT update_id,state FROM inbox ORDER BY update_id DESC LIMIT 4")]
  db.close()
  found=[]
  for key,state in keys:
   matches=[x for x in info.get("assignments",[]) if x.get("idempotencyKey")==key]
   found.append({"local_state":state,"bridge_matched":len(matches),"bridge_state":matches[0].get("state") if len(matches)==1 else None,"dispatch_count":matches[0].get("dispatchCount") if len(matches)==1 else None,"dispatch_submit_attempted":matches[0].get("dispatchSubmitAttempted") if len(matches)==1 else None,"result_ack":bool(matches[0].get("result")) if len(matches)==1 else False})
  out["bridge_assignments"]={"total":len(info.get("assignments",[])),"matches":found}
 except Exception as e:out["bridge_assignments"]={"error_type":type(e).__name__,"error_code":str(e)[:90] if type(e).__name__=="Blocked" else ""}
except Exception as e:out["fatal"]={"error_type":type(e).__name__}
print(json.dumps(out,ensure_ascii=True))
